"""lever_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +y from 3 extrusion(s) and 2 cut(s), applied in order;
each is an outline in the xz plane between two levels. Units: mm.
Run:  python lever_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = -24.0    # level along y
z1 = 0.0    # level along y
z2 = 6.0    # level along y
z3 = 14.0    # level along y
hole_d1 = 6.0
hole_d2 = 20.0

DIR = (0, 1, 0)


def P(a, b):
    """Point (x, z) in the sketch plane (y = 0)."""
    return (a, 0, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: y -24.0 to 0.0 ------------------------------
outline_1 = cf.wire(
    Edge.makeCircle(9.0, P(38.0, 0.0), DIR),
)
part = prism(outline_1, z0, z1)

# ---- 2. extrusion: y 0.0 to 6.0 ------------------------------
outline_2 = cf.wire(
    cf.segment(P(2.9474, 15.7262), P(39.6579, 8.846)),
    Edge.makeThreePointArc(P(39.6579, 8.846), P(47.0, 0.0), P(39.6579, -8.846)),
    cf.segment(P(39.6579, -8.846), P(2.9474, -15.7262)),
    Edge.makeThreePointArc(P(2.9474, -15.7262), P(-16.0, 0.0), P(2.9474, 15.7262)),
)
part = part + prism(outline_2, z1, z2)

# ---- 3. extrusion: y 6.0 to 14.0 ------------------------------
outline_3 = cf.wire(
    Edge.makeCircle(16.0, P(0.0, 0.0), DIR),
)
part = part + prism(outline_3, z2, z3)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (38.0, 0.0, hole_d1, z0, z2),
    (0.0, 0.0, hole_d2, z1, z3),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "lever_exact.step")
